//! Opaque tonic transport: identity views and bounded complete gzip messages.

#![cfg(feature = "tonic")]

#[cfg(feature = "tonic-gzip")]
use bytes::Buf;
use bytes::{Bytes, BytesMut};
use http::{Request, Response};
use http_body::{Body, Frame};
use pbrs_grpc::tonic_server::TonicServerExt;
use pbrs_grpc::{Server, ServerConfig};
use std::collections::VecDeque;
use std::future::{Future, poll_fn};
use std::pin::Pin;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::task::{Context, Poll};
use std::time::Duration;
use tonic::body::Body as TonicBody;
use tonic::server::NamedService;
use tower::Service;

#[derive(Clone)]
struct Probe {
    output: Vec<Bytes>,
    state: Arc<State>,
    read_input: bool,
    decode_input: bool,
    encoding: Option<&'static str>,
    pending_tail: bool,
    disable_compression: bool,
    content_length: Option<usize>,
    body_error: bool,
}

#[derive(Default)]
struct State {
    ready: AtomicUsize,
    calls: AtomicUsize,
    dropped: AtomicUsize,
    input_dropped: AtomicUsize,
    input_content_length: AtomicUsize,
    #[cfg(feature = "tonic-gzip")]
    decoded_calls: AtomicUsize,
}

#[cfg(feature = "tonic-gzip")]
struct HelloDecoder;
#[cfg(feature = "tonic-gzip")]
impl tonic::codec::Decoder for HelloDecoder {
    type Item = pbrs_grpc::hello::HelloRequest;
    type Error = tonic::Status;

    fn decode(
        &mut self,
        input: &mut tonic::codec::DecodeBuf<'_>,
    ) -> Result<Option<Self::Item>, Self::Error> {
        pbrs::Parse::parse_bytes(input.copy_to_bytes(input.remaining()))
            .map(Some)
            .map_err(|error| tonic::Status::internal(error.to_string()))
    }
}

struct InputDrop(Arc<State>);
impl Drop for InputDrop {
    fn drop(&mut self) {
        self.0.input_dropped.fetch_add(1, Ordering::SeqCst);
    }
}

impl NamedService for Probe {
    const NAME: &'static str = "test.IdentityCaps";
}

impl Service<Request<TonicBody>> for Probe {
    type Response = Response<Frames>;
    type Error = tonic::Status;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;

    fn poll_ready(&mut self, _: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.state.ready.fetch_add(1, Ordering::SeqCst);
        Poll::Ready(Ok(()))
    }

    fn call(&mut self, request: Request<TonicBody>) -> Self::Future {
        self.state.calls.fetch_add(1, Ordering::SeqCst);
        self.state.input_content_length.store(
            request
                .headers()
                .get("content-length")
                .and_then(|value| value.to_str().ok())
                .and_then(|value| value.parse().ok())
                .unwrap_or(0),
            Ordering::SeqCst,
        );
        let probe = self.clone();
        Box::pin(async move {
            let mut frames = VecDeque::new();
            if probe.decode_input {
                #[cfg(feature = "tonic-gzip")]
                {
                    let _guard = InputDrop(probe.state.clone());
                    let mut input = tonic::Streaming::new_request(
                        HelloDecoder,
                        request.into_body(),
                        Some(tonic::codec::CompressionEncoding::Gzip),
                        None,
                    );
                    while let Some(message) = input.message().await? {
                        let encoded = pbrs::Serialize::serialize(&message)
                            .map_err(|error| tonic::Status::internal(error.to_string()))?;
                        frames.push_back(Ok(Frame::data(identity_wire(&encoded))));
                        probe.state.decoded_calls.fetch_add(1, Ordering::SeqCst);
                    }
                }
                #[cfg(not(feature = "tonic-gzip"))]
                return Err(tonic::Status::unimplemented(
                    "the independent gzip oracle requires tonic-gzip",
                ));
            } else if probe.read_input {
                let _guard = InputDrop(probe.state.clone());
                let mut body = request.into_body();
                while let Some(frame) = poll_fn(|cx| Pin::new(&mut body).poll_frame(cx)).await {
                    if let Ok(bytes) = frame?.into_data() {
                        frames.push_back(Ok(Frame::data(bytes)));
                    }
                }
            } else {
                frames.extend(
                    probe
                        .output
                        .iter()
                        .cloned()
                        .map(|bytes| Ok(Frame::data(bytes))),
                );
            }
            if probe.body_error {
                let mut metadata = tonic::metadata::MetadataMap::new();
                metadata.insert(
                    "x-terminal",
                    tonic::metadata::MetadataValue::from_static("preserved"),
                );
                frames.push_back(Err(tonic::Status::with_details_and_metadata(
                    tonic::Code::PermissionDenied,
                    "producer body error",
                    Bytes::from_static(b"details"),
                    metadata,
                )));
            } else if !probe.pending_tail {
                let mut trailers = http::HeaderMap::new();
                trailers.insert("grpc-status", http::HeaderValue::from_static("0"));
                trailers.insert("x-terminal", http::HeaderValue::from_static("preserved"));
                frames.push_back(Ok(Frame::trailers(trailers)));
            }
            let mut response = Response::builder()
                .header("content-type", "application/grpc")
                .header("x-initial", "preserved");
            if let Some(encoding) = probe.encoding {
                response = response.header("grpc-encoding", encoding);
            }
            if let Some(length) = probe.content_length {
                response = response.header("content-length", length.to_string());
            }
            let mut response = response
                .body(Frames {
                    frames,
                    state: probe.state,
                    pending_tail: probe.pending_tail,
                })
                .map_err(|error| tonic::Status::internal(error.to_string()))?;
            if probe.disable_compression {
                response
                    .extensions_mut()
                    .insert(tonic::codec::SingleMessageCompressionOverride::Disable);
            }
            Ok(response)
        })
    }
}

struct Frames {
    frames: VecDeque<Result<Frame<Bytes>, tonic::Status>>,
    state: Arc<State>,
    pending_tail: bool,
}
impl Drop for Frames {
    fn drop(&mut self) {
        self.state.dropped.fetch_add(1, Ordering::SeqCst);
    }
}
impl Body for Frames {
    type Data = Bytes;
    type Error = tonic::Status;

    fn poll_frame(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
    ) -> Poll<Option<Result<Frame<Bytes>, Self::Error>>> {
        match self.frames.pop_front() {
            Some(frame) => Poll::Ready(Some(frame)),
            None if self.pending_tail => Poll::Pending,
            None => Poll::Ready(None),
        }
    }
}

struct Tasks(Vec<tokio::task::JoinHandle<()>>);
impl Drop for Tasks {
    fn drop(&mut self) {
        for task in &self.0 {
            task.abort();
        }
    }
}

struct Fixture {
    client: h2::client::SendRequest<Bytes>,
    _tasks: Tasks,
    state: Arc<State>,
}

async fn connect(service: Probe, config: ServerConfig, window: u32) -> Fixture {
    connect_with_tracker(service, config, window, None).await
}

#[expect(
    clippy::expect_used,
    reason = "transport fixture setup must fail the test on error"
)]
async fn connect_with_tracker(
    service: Probe,
    config: ServerConfig,
    window: u32,
    tracker: Option<pbrs_grpc::ByteBudgetTracker>,
) -> Fixture {
    let state = service.state.clone();
    let (client, io) = tokio::io::duplex(64 * 1024);
    let mut server = Server::new(service.into_pbrs_service()).config(config);
    if let Some(tracker) = tracker {
        server = server.with_byte_budget_tracker(tracker);
    }
    let serving = tokio::spawn(async move {
        server.serve_connection(io).await.expect("server");
    });
    let (client, connection) = h2::client::Builder::new()
        .initial_window_size(window)
        .handshake(client)
        .await
        .expect("handshake");
    let driver = tokio::spawn(async move {
        connection.await.ok();
    });
    Fixture {
        client,
        _tasks: Tasks(vec![serving, driver]),
        state,
    }
}

#[expect(clippy::expect_used, reason = "the fixed test request must be valid")]
fn request() -> Request<()> {
    Request::builder()
        .method("POST")
        .uri("http://localhost/test.IdentityCaps/Call")
        .header("content-type", "application/grpc")
        .body(())
        .expect("request")
}

#[expect(
    clippy::expect_used,
    reason = "unexpected fixture transport failures must fail the test"
)]
async fn exchange(
    fixture: &mut Fixture,
    request: Request<()>,
    upload: Vec<Bytes>,
) -> (Bytes, http::HeaderMap, http::HeaderMap) {
    let (response, mut send) = fixture
        .client
        .send_request(request, upload.is_empty())
        .expect("request");
    let mut upload = upload.into_iter().peekable();
    while let Some(bytes) = upload.next() {
        send.send_data(bytes, upload.peek().is_none())
            .expect("upload");
    }
    collect(response.await.expect("response")).await
}

#[expect(
    clippy::expect_used,
    reason = "unexpected DATA, credit or trailer failures must fail the test"
)]
async fn collect(response: Response<h2::RecvStream>) -> (Bytes, http::HeaderMap, http::HeaderMap) {
    let headers = response.headers().clone();
    let mut body = response.into_body();
    let mut bytes = BytesMut::new();
    while let Some(data) = body.data().await {
        let data = data.expect("data");
        body.flow_control()
            .release_capacity(data.len())
            .expect("credit");
        bytes.extend_from_slice(&data);
    }
    let terminal = body
        .trailers()
        .await
        .expect("trailers")
        .unwrap_or_else(|| headers.clone());
    (bytes.freeze(), terminal, headers)
}

fn probe(output: Vec<Bytes>) -> Probe {
    Probe {
        output,
        state: Arc::new(State::default()),
        read_input: false,
        decode_input: false,
        encoding: None,
        pending_tail: false,
        disable_compression: false,
        content_length: None,
        body_error: false,
    }
}

#[expect(
    clippy::expect_used,
    reason = "gzip test fixtures must encode successfully"
)]
fn gzip_wire(payload: &[u8]) -> Bytes {
    let encoded = pbrs_grpc::gzip::encode(payload).expect("gzip");
    let len = u32::try_from(encoded.len()).expect("small fixture");
    let mut wire = vec![1];
    wire.extend_from_slice(&len.to_be_bytes());
    wire.extend_from_slice(&encoded);
    Bytes::from(wire)
}

#[expect(
    clippy::expect_used,
    reason = "fixed gzip-member test fixtures must encode within the wire length limit"
)]
fn gzip_members_wire(members: &[&[u8]]) -> Bytes {
    let mut encoded = Vec::new();
    for member in members {
        encoded.extend(pbrs_grpc::gzip::encode(member).expect("gzip member"));
    }
    let mut bytes = vec![1];
    bytes.extend_from_slice(
        &u32::try_from(encoded.len())
            .expect("small fixture")
            .to_be_bytes(),
    );
    bytes.extend(encoded);
    Bytes::from(bytes)
}

