//! Ownership and budget controls for stream-owned plaintext scratch.
#![allow(clippy::expect_used, clippy::panic, reason = "bounded test assertions")]

use super::*;
use crate::transport::{ClientBuilder as _, SendRequest as _};
use crate::workspace::{RetainedEncodeLease, retained_encode_counts};
use std::cell::RefCell;
use std::future::{Future, poll_fn};
use std::pin::Pin;
use std::task::Poll;

struct Fill(usize);
impl CodecMessage for Fill {
    const USE_APPEND_ONLY_ENCODE: bool = true;
    fn encoded_len(&self) -> usize {
        self.0
    }
    fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
        let block = [0x42; 4096];
        let mut left = self.0;
        while left != 0 {
            let take = left.min(block.len());
            out.put_slice(block.get(..take).expect("block range"));
            left -= take;
        }
        Ok(())
    }
    fn decode_payload(_: Bytes) -> Result<Self, Status> {
        Ok(Self(0))
    }
    fn empty() -> Self {
        Self(0)
    }
}

#[test]
fn errors_and_caught_panics_leave_original_scratch_empty() {
    let mut scratch = EncodeScratch::new();
    scratch
        .with_payload(&Fill(1024), 1024, |_| Ok(()))
        .expect("warm small");
    assert_eq!(scratch.capacity(), 1024);
    let error = scratch
        .with_payload(&Fill(128 * 1024), 128 * 1024, |_| -> Result<(), Status> {
            Err(Status::internal("compressor failed"))
        })
        .expect_err("error");
    assert_eq!(error.code(), crate::Code::Internal);
    assert!(scratch.has_no_buffer());
    let panic = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        scratch.with_payload(&Fill(128 * 1024), 128 * 1024, |_| -> Result<(), Status> {
            panic!("compressor panicked")
        })
    }));
    assert!(panic.is_err());
    assert!(scratch.has_no_buffer());

    struct Partial;
    impl CodecMessage for Partial {
        fn encoded_len(&self) -> usize {
            128 * 1024
        }
        fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
            out.put_slice(b"partial");
            Err(Status::aborted("encoder failed"))
        }
        fn decode_payload(_: Bytes) -> Result<Self, Status> {
            Ok(Self)
        }
        fn empty() -> Self {
            Self
        }
    }
    assert!(
        scratch
            .with_payload(&Partial, Partial.encoded_len(), |_| Ok(()))
            .is_err()
    );
    assert!(scratch.has_no_buffer());

    struct Panic;
    impl CodecMessage for Panic {
        fn encoded_len(&self) -> usize {
            128 * 1024
        }
        fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
            out.put_slice(b"partial");
            panic!("encoder panicked")
        }
        fn decode_payload(_: Bytes) -> Result<Self, Status> {
            Ok(Self)
        }
        fn empty() -> Self {
            Self
        }
    }
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            scratch.with_payload(&Panic, Panic.encoded_len(), |_| Ok(()))
        }))
        .is_err()
    );
    assert!(scratch.has_no_buffer());
}

#[test]
fn canonical_capacity_handles_growth_and_retention_policy_boundaries() {
    let mut scratch = EncodeScratch::new();
    for size in [
        0,
        1024,
        65536,
        65537,
        1024,
        4 * 1024 * 1024,
        4 * 1024 * 1024 + 1,
    ] {
        // An underestimated hint must not hide actual backing capacity.
        scratch
            .with_payload(&Fill(size), 1, |body| {
                assert_eq!(body.len(), size);
                assert!(body.iter().all(|byte| *byte == 0x42));
                Ok(())
            })
            .expect("encode");
        let capacity = scratch.capacity();
        if capacity <= MAX_RETAINED_SCRATCH_BYTES {
            assert!(scratch.lease_capacity().is_none());
        } else {
            assert!(capacity <= 4 * 1024 * 1024);
            assert_eq!(scratch.lease_capacity(), Some(capacity));
        }
        if size > 4 * 1024 * 1024 {
            assert!(scratch.has_no_buffer());
        }
    }
}

#[test]
fn legacy_contiguous_aliases_never_receive_canonical_leases() {
    struct Custom<'a> {
        retained: &'a RefCell<Vec<Bytes>>,
        mode: u8,
    }
    impl CodecMessage for Custom<'_> {
        fn encoded_len(&self) -> usize {
            70 * 1024
        }
        fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
            out.write_contiguous(|buf| {
                // Legacy codecs retain direct mutable access. Replacing and
                // splitting it may pin more application storage than the
                // visible output window; no canonical lease is inferred.
                assert!(buf.is_empty());
                *buf = BytesMut::with_capacity(2 * self.encoded_len());
                buf.resize(self.encoded_len(), 0x5a);
                match self.mode {
                    0 => {
                        buf.extend_from_slice(b"retained tail");
                        let tail = buf.split_off(self.encoded_len());
                        self.retained.borrow_mut().push(tail.freeze());
                    }
                    1 => self.retained.borrow_mut().push(buf.split_to(0).freeze()),
                    2 => {
                        let replacement = BytesMut::from(buf.as_ref());
                        self.retained
                            .borrow_mut()
                            .push(std::mem::replace(buf, replacement).freeze());
                    }
                    _ => {}
                }
                Ok(())
            })
        }
        fn decode_payload(_: Bytes) -> Result<Self, Status> {
            panic!("encode-only fixture")
        }
        fn empty() -> Self {
            panic!("encode-only fixture")
        }
    }
    for mode in 0..3 {
        let aliases = RefCell::new(Vec::new());
        let message = Custom {
            retained: &aliases,
            mode,
        };
        let mut scratch = EncodeScratch::new();
        for _ in 0..2 {
            scratch
                .with_payload(&message, message.encoded_len(), |body| {
                    assert_eq!(body.len(), message.encoded_len());
                    assert!(body.iter().all(|byte| *byte == 0x5a));
                    Ok(())
                })
                .expect("legacy mutable sink");
            assert!(scratch.lease_capacity().is_none());
            assert!(scratch.has_no_buffer());
        }
        drop(scratch);
        assert_eq!(aliases.borrow().len(), 2);
        if mode == 0 {
            assert!(
                aliases
                    .borrow()
                    .iter()
                    .all(|alias| alias.as_ref() == b"retained tail")
            );
        }
    }
}

#[test]
fn legacy_contiguous_small_scratch_is_direct_and_reused() {
    struct Legacy<'a> {
        bytes: usize,
        pointers: &'a RefCell<Vec<usize>>,
    }
    impl CodecMessage for Legacy<'_> {
        fn encoded_len(&self) -> usize {
            self.bytes
        }
        fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
            out.write_contiguous(|bytes| {
                assert!(bytes.capacity() >= self.bytes);
                self.pointers.borrow_mut().push(bytes.as_ptr() as usize);
                bytes.resize(self.bytes, 0x91);
            });
            Ok(())
        }
        fn encode_payload_bufmut<B: bytes::BufMut>(&self, _: &mut B) -> Result<(), Status> {
            panic!("default-off legacy path must not use the append-only bridge")
        }
        fn decode_payload(_: Bytes) -> Result<Self, Status> {
            panic!("encode only")
        }
        fn empty() -> Self {
            panic!("encode only")
        }
    }
    let pointers = RefCell::new(Vec::new());
    let message = Legacy {
        bytes: 1024,
        pointers: &pointers,
    };
    let mut scratch = EncodeScratch::new();
    for _ in 0..4 {
        scratch
            .with_payload(&message, message.encoded_len(), |bytes| {
                assert_eq!(bytes, vec![0x91; 1024]);
                Ok(())
            })
            .expect("legacy direct encode");
        assert_eq!(scratch.capacity(), 1024);
        assert!(scratch.lease_capacity().is_none());
    }
    let pointers = pointers.borrow();
    assert_eq!(pointers.len(), 4);
    let first = pointers.first().expect("four recorded pointers");
    assert!(pointers.iter().all(|pointer| pointer == first));
}

#[test]
fn codec_modes_release_old_storage_and_keep_distinct_retention_rules() {
    struct Legacy(usize);
    impl CodecMessage for Legacy {
        fn encoded_len(&self) -> usize {
            self.0
        }
        fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
            out.write_contiguous(|bytes| bytes.resize(self.0, 0x73));
            Ok(())
        }
        fn decode_payload(_: Bytes) -> Result<Self, Status> {
            Ok(Self(0))
        }
        fn empty() -> Self {
            Self(0)
        }
    }
    let mut scratch = EncodeScratch::new();
    scratch
        .with_payload(&Fill(1024), 1024, |_| Ok(()))
        .expect("canonical warm");
    assert!(matches!(scratch, EncodeScratch::Canonical { .. }));
    scratch
        .with_payload(&Legacy(1024), 1024, |_| Ok(()))
        .expect("legacy switch");
    assert!(matches!(scratch, EncodeScratch::Legacy(_)));
    assert!(scratch.lease_capacity().is_none());
    scratch
        .with_payload(&Legacy(1024 * 1024), 1024 * 1024, |bytes| {
            assert_eq!(bytes.len(), 1024 * 1024);
            Ok(())
        })
        .expect("legacy large");
    assert!(
        scratch.has_no_buffer(),
        "large legacy storage is never retained"
    );
    scratch
        .with_payload(&Fill(1024), 1024, |_| Ok(()))
        .expect("canonical switch");
    assert!(matches!(scratch, EncodeScratch::Canonical { .. }));
}

fn assert_no_large_scratch() {
    let counts = retained_encode_counts();
    assert_eq!(counts.retained_capacity, 0);
    assert_eq!(counts.retained_buffers, 0);
    assert_eq!(counts.acquired, counts.released);
}

async fn pending_once<F: Future>(mut future: Pin<&mut F>) {
    poll_fn(|cx| {
        assert!(future.as_mut().poll(cx).is_pending());
        Poll::Ready(())
    })
    .await;
}

async fn completed_kept_alive<F: Future>(mut future: Pin<&mut F>) -> F::Output {
    tokio::time::timeout(
        std::time::Duration::from_secs(2),
        poll_fn(|cx| future.as_mut().poll(cx)),
    )
    .await
    .expect("bounded terminal poll")
}

async fn local_send() -> (
    crate::transport::h2::SendStream,
    crate::transport::h2::ResponseFuture,
    crate::transport::h2::ClientConnection<tokio::io::DuplexStream>,
    tokio::io::DuplexStream,
) {
    // A complete compressed frame fits local credit and send buffering. Keep
    // both endpoints alive; these are cleanup controls, not wire-interop proof.
    let (io, peer) = tokio::io::duplex(65536);
    let (mut request, driver) = tokio::time::timeout(
        std::time::Duration::from_secs(2),
        crate::transport::h2::ClientBuilder::new().handshake(io),
    )
    .await
    .expect("bounded local handshake")
    .expect("h2 client");
    let (response, send) = request
        .send_request(
            http::Request::builder()
                .uri("http://localhost/encode/scratch")
                .body(())
                .expect("request"),
            false,
        )
        .expect("open stream");
    (send, response, driver, peer)
}

async fn actual_terminal_owners() {
    use crate::server::drain::{CancelFlag, drain_to_wire};
    use crate::telemetry::CallLabels;
    use crate::wire::send::{PumpEnd, pump_outbound};
    for end in [0u8, 1, 2, 3] {
        let (mut send, _response, _driver, _peer) = local_send().await;
        let (sender, stream) = crate::Streaming::channel(4);
        sender
            .send_compressed(Fill(1024 * 1024))
            .await
            .expect("message");
        let cancel = crate::rpc_cancel::RpcCancel::new();
        let signal = cancel.clone();
        let mut pump = Box::pin(pump_outbound(
            &mut send,
            stream,
            cancel,
            crate::ChannelConfig::new().wire(),
        ));
        pending_once(pump.as_mut()).await;
        assert_eq!(retained_encode_counts().retained_capacity, 1024 * 1024);
        match end {
            0 => {
                drop(sender);
                assert!(matches!(
                    completed_kept_alive(pump.as_mut()).await,
                    PumpEnd::HalfClosed
                ));
                assert_no_large_scratch(); // pump remains allocated after Ready
                drop(pump);
            }
            1 => {
                signal.signal();
                assert!(matches!(
                    completed_kept_alive(pump.as_mut()).await,
                    PumpEnd::Reset
