                sender.fail(Status::aborted("producer failed")).await;
                match completed_kept_alive(pump.as_mut()).await {
                    PumpEnd::Failed(status) => assert_eq!(status.code(), crate::Code::Aborted),
                    _ => panic!("producer status"),
                }
                assert_no_large_scratch();
                drop(pump);
            }
            _ => {
                drop(pump);
                drop(sender);
            }
        }
        assert_no_large_scratch();
    }
