        let (mut send, _response, _driver, _peer) = local_send().await;
        let (sender, mut stream) = crate::Streaming::channel(4);
        sender
            .send_compressed(Fill(1024 * 1024))
            .await
            .expect("message");
        let mut wire = crate::ServerConfig::new().wire();
        wire.limits = wire.limits.with_max_encoding(1024 * 1024);
        let budget = crate::ByteBudgetTracker::unlimited();
        let call = CancelFlag::new();
        let labels = CallLabels::UNLABELED_SERVER;
        let mut drain = Box::pin(drain_to_wire(
            &mut stream,
            &mut send,
            wire,
            Some(true),
            true,
            true,
            false,
            #[cfg(feature = "zstd")]
            false,
            &budget,
            None,
            &labels,
            None,
            None,
            &call,
            false,
        ));
        pending_once(drain.as_mut()).await;
        assert_eq!(retained_encode_counts().retained_capacity, 1024 * 1024);
        match end {
            0 => {
                drop(sender);
                assert!(completed_kept_alive(drain.as_mut()).await.is_ok());
                assert_no_large_scratch(); // drain remains allocated after Ready
                drop(drain);
            }
            1 => {
                sender
                    .send_compressed(Fill(2 * 1024 * 1024))
                    .await
                    .expect("queued oversize for drain cap");
                assert!(completed_kept_alive(drain.as_mut()).await.is_err());
                assert_no_large_scratch();
                drop(drain);
                drop(sender);
            }
            _ => {
                drop(drain);
                drop(sender);
            }
        }
        assert_no_large_scratch();
        assert_eq!(budget.allocated(), 0);
        assert_eq!(budget.active_byte_permit_tokens(), 0);
    }
}

