            Ok(())
        })
        .expect("switch releases old canonical lease before legacy encoding");
    assert!(matches!(scratch, EncodeScratch::Legacy(_)));
    scratch
        .with_payload(&Fill(128 * 1024), 128 * 1024, |_| {
            assert_no_large_scratch();
            Ok(())
        })
        .expect("legacy-to-canonical switch remains accounted");
    assert_eq!(retained_encode_counts().retained_capacity, 128 * 1024);
    drop(scratch);
    assert_no_large_scratch();
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    runtime.block_on(actual_terminal_owners());
    assert_no_large_scratch();
    let counts = retained_encode_counts();
    eprintln!(
        "C15_ENCODE_RESOURCE acquired={} released={} retained_capacity={} retained_buffers={} scratch_size={} batch_size={}",
        counts.acquired,
        counts.released,
        counts.retained_capacity,
        counts.retained_buffers,
        std::mem::size_of::<EncodeScratch>(),
        std::mem::size_of::<crate::wire::out_batch::OutBatch>()
    );
}

